}

.payment-amount strong {
  color: #08263a;
  font-size: 1.1rem;
}

.payment-open {
  color: #b58b4a;
  font-weight: 800;
  text-align: right;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

