  font-family: "Raleway", Arial, sans-serif;
  font-size: clamp(1.05rem, 3vw, 1.3rem);
}

.booking-payment-header p {
  margin: 0;
  color: #516070;
  font-size: 0.9rem;
}

.booking-status {
