}

.booking-status.status-warning {
  background: rgba(242, 140, 40, 0.16);
  color: #9a5a12;
}

.booking-status.status-balance {
  background: rgba(11, 110, 143, 0.13);
  color: #0b6e8f;
}

.booking-status.status-paid {
  background: rgba(4, 120, 87, 0.13);
  color: #047857;
}

.booking-status.status-completed {
  background: rgba(8, 38, 58, 0.1);
  color: #08263a;
}

.booking-payment-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
}

.booking-payment-panel {
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 18px;
  background: #fbf8f2;
  padding: 0.95rem;
  display: grid;
  gap: 0.55rem;
}

.booking-payment-panel.highlight-panel {
  background: rgba(4, 120, 87, 0.07);
  border-color: rgba(4, 120, 87, 0.18);
}

.booking-payment-panel.warranty-panel {
  background: rgba(181, 139, 74, 0.09);
  border-color: rgba(181, 139, 74, 0.2);
}

.panel-label {
  color: #516070;
  font-weight: 800;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.amount-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  border-top: 1px solid rgba(8, 38, 58, 0.08);
  padding-top: 0.45rem;
  color: #516070;
}

.amount-line:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.amount-line strong {
  color: #08263a;
  white-space: nowrap;
}

.amount-line.total-line strong {
  font-size: 1.2rem;
}

.compact-action {
  justify-self: start;
  margin-top: 0.35rem;
  padding: 0.65rem 0.9rem;
  min-height: 38px;
  font-size: 0.88rem;
}

.booking-payment-panel small {
  color: #516070;
  line-height: 1.5;
}

