  border-top: 1px solid rgba(8, 38, 58, 0.08);
  padding-top: 0.75rem;
  display: grid;
  gap: 0.45rem;
}

.booking-payment-records > span {
  color: #516070;
  font-weight: 800;
  font-size: 0.82rem;
}

.mini-payment {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.75rem;
  align-items: center;
  font-size: 0.9rem;
  color: #516070;
}

.mini-payment strong {
  color: #08263a;
}

.mini-payment small {
  color: #697789;
}

@media (max-width: 760px) {
  .booking-payment-toolbar,
  .booking-payment-grid {
    grid-template-columns: 1fr;
  }
